@file:OptIn(InternalResourceApi::class)

package com.neoutils.neoregex.core.resources

import kotlin.OptIn
import kotlin.String
import kotlin.collections.MutableMap
import org.jetbrains.compose.resources.FontResource
import org.jetbrains.compose.resources.InternalResourceApi
import org.jetbrains.compose.resources.ResourceItem

private const val MD: String = "composeResources/com.neoutils.neoregex.core.resources/"

public val Res.font.jetbrains_mono: FontResource by lazy {
      FontResource("font:jetbrains_mono", setOf(
        ResourceItem(setOf(), "${MD}font/jetbrains_mono.ttf", -1, -1),
      ))
    }

public val Res.font.roboto_mono: FontResource by lazy {
      FontResource("font:roboto_mono", setOf(
        ResourceItem(setOf(), "${MD}font/roboto_mono.ttf", -1, -1),
      ))
    }

@InternalResourceApi
internal fun _collectCommonMainFont0Resources(map: MutableMap<String, FontResource>) {
  map.put("jetbrains_mono", Res.font.jetbrains_mono)
  map.put("roboto_mono", Res.font.roboto_mono)
}
